def _sade(m):
    t = str(m or '').translate(str.maketrans({'İ': 'i', 'I': 'i', 'ı': 'i', 'Ç': 'c', 'ç': 'c', 'Ş': 's', 'ş': 's',
                                               'Ğ': 'g', 'ğ': 'g', 'Ö': 'o', 'ö': 'o', 'Ü': 'u', 'ü': 'u'}))
    return ' '.join(t.lower().split())


def urunleri_yukle(apps, schema_editor):
    """Excel'deki 43 temizlik ürününü yükler (tablo boşsa); sevkiyat kataloğunda aynı adlı ürün varsa bağlar."""
    TemizlikUrun = apps.get_model('panel', 'TemizlikUrun')
    Urun = apps.get_model('panel', 'Urun')
    if TemizlikUrun.objects.exists():
        return
    katalog = {}
    for u in Urun.objects.all():
        katalog.setdefault(_sade(u.ad), u)
    for sira, (ad, icerik, birim) in enumerate(TEMIZLIK_URUNLERI, 1):
        TemizlikUrun.objects.create(ad=ad, koli_icerigi=icerik, birim=birim, sira=sira,
                                    urun=katalog.get(_sade(ad)))


